"""Builds dist/worker-cloudflare.js: the worker as one file for pasting into the Cloudflare dashboard editor."""
import os
import re

ROOT = os.path.join(os.path.dirname(__file__), "..")


def read(path):
    with open(os.path.join(ROOT, path), encoding="utf-8") as f:
        return f.read()


def strip(s):
    return re.sub(r"^export (?!default)", "", s, flags=re.M)


index = re.sub(r"^import .*?;\n", "", read("worker/src/index.js"), flags=re.M | re.S)
out = ("// Rahoitusvahti idea search - single-file version for pasting into the Cloudflare dashboard editor.\n"
       "// Generated by collector/build_worker.py from worker/src/index.js, web/idea-prompt.js and web/describe-prompt.js.\n\n"
       + strip(read("web/idea-prompt.js")) + "\n" + strip(read("web/describe-prompt.js")) + "\n" + index)
os.makedirs(os.path.join(ROOT, "dist"), exist_ok=True)
with open(os.path.join(ROOT, "dist", "worker-cloudflare.js"), "w", encoding="utf-8") as f:
    f.write(out)
print("dist/worker-cloudflare.js", len(out) // 1024, "kB")
